import { Component, createContext, For, JSX, Show, useContext } from "solid-js";

import { Activatable, EMPTY_ACTIVATABLE_AUDIO } from "#core/ui-next/components/activatable.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { HeroButton2 } from "#core/ui-next/components/hero-button.jsx";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import {
	createPauseMenuModel,
	GameInfoProps,
	LeaderPortraitAreaProps,
	PauseMenuAddonInfoSectionProps,
	PauseMenuContextModel,
	PauseMenuProgressionBadgeProps,
} from "#base/ui-next/screens/pause-menu/pause-menu-model.js";

import style from "#base/ui-next/screens/pause-menu/pause-menu.scss?url";

const PauseMenuContext = createContext<PauseMenuContextModel>();

function usePauseMenuContext() {
	const context = useContext(PauseMenuContext);

	if (!context) {
		throw new Error("Unable to get pause menu context!");
	}

	return context;
}

//#region Button Container
const PauseMenuButtonContainer: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	const model = usePauseMenuContext();
	return (
		<VSlot
			{...props}
			class="pause-menu-button-container"
			data-name="pause-menu-button-container"
			id="pause-menu-button-container"
			autoFocus={true}
		>
			<Hotkeys hotkeys={[{ hotkeyAction: "sys-menu", onActivate: model.onClickResume }]} />
			<HeroButton2
				id="pause-menu-resume-button"
				class="pause-menu-button bottom-padding"
				onActivate={model.onClickResume}
				hotkeyAction="cancel"
				autoFocus={true}
			>
				<L10n.Compose text="LOC_GENERIC_RESUME" />
			</HeroButton2>
			<Button
				class="pause-menu-button"
				onActivate={model.onClickQuickSave}
			>
				<L10n.Compose text="LOC_QUICK_SAVE_NAME" />
			</Button>
			<Button
				class="pause-menu-button"
				onActivate={model.onClickSave}
			>
				<L10n.Compose text="LOC_PAUSE_MENU_SAVE" />
			</Button>
			<Show when={!model.isMultiplayer}>
				<Button
					class="pause-menu-button"
					onActivate={model.onClickLoad}
				>
					<L10n.Compose text="LOC_PAUSE_MENU_LOAD" />
				</Button>
				<Show
					when={model.data.canRestart}
					fallback={
						<Tooltip.Text text={model.data.restartButtonDisabledReason!}>
							<Button class="pause-menu-button disabled">
								<L10n.Compose text="LOC_PAUSE_MENU_RESTART" />
							</Button>
						</Tooltip.Text>
					}
				>
					<Button
						class="pause-menu-button"
						onActivate={model.onClickRestart}
					>
						<L10n.Compose text="LOC_PAUSE_MENU_RESTART" />
					</Button>
				</Show>
				<Button
					class="pause-menu-button"
					onActivate={model.onClickRetire}
				>
					<L10n.Compose text={model.data.retireButtonString} />
				</Button>
			</Show>
			<Button
				class="pause-menu-button bottom-padding"
				onActivate={model.onClickOptions}
			>
				<L10n.Compose text="LOC_PAUSE_MENU_OPTIONS" />
			</Button>
			<Show when={model.isMultiplayer && model.shouldShowJoinCode}>
				<Button
					class="pause-menu-button"
					onActivate={model.onClickJoinCode}
				>
					<L10n.Compose text={model.joinCodeString} />
				</Button>
			</Show>
			<Button
				class="pause-menu-button"
				onActivate={model.onClickExitToMain}
			>
				<L10n.Compose text="LOC_END_GAME_EXIT" />
			</Button>
			<Show when={model.data?.canExitToDesktop}>
				<Button
					class="pause-menu-button"
					onActivate={model.onClickExitToDesktop}
				>
					<L10n.Compose text="LOC_PAUSE_MENU_QUIT_TO_DESKTOP" />
				</Button>
			</Show>
		</VSlot>
	);
};
//#endregion

//#region Progression Badge
const PauseMenuProgressionContainer: Component<PauseMenuProgressionBadgeProps> = (props) => {
	const model = usePauseMenuContext();

	return (
		<Activatable
			{...props}
			class="relative hover\:scale-105 transition-transform"
			onActivate={model.onClickProgression}
			disableFocus={true}
			hotkeyAction="shell-action-1"
			style={{ "transition-duration": "0.1s" }}
		>
			<div class="pause-menu-progression-border p-1">
				<div
					class="bg-cover bg-no-repeat p-1"
					style={{ "background-image": `url(${props.backgroundImage})` }}
				>
					<div class="relative flex flow-row justify-between">
						<div class="w-64 flex-auto flex-initial h-full">
							<div class="flow-column max-w-full">
								<div class="flow-row items-center">
									<Show when={model.supportsSSO}>
										<div
											class="w-7 h-7 mr-2 mb-2 bg-cover bg-no-repeat"
											style={{ "background-image": `url(${props.firstPartyIcon})` }}
										/>
									</Show>
									<div class="flex-auto flow-row items-center mb-2">
										<div class="font-body text-base text-header-4 text-shadow font-fit-shrink whitespace-nowrap flex">
											{props.firstPartyName}
										</div>
									</div>
								</div>
								<Show when={model.supportsSSO}>
									<div class="flow-row items-center">
										<div
											class="w-6 h-6 mr-2\.5 ml-0\.5 bg-cover bg-no-repeat"
											style={{ "background-image": "url(blp:prof_2k_logo)" }}
										/>
										<div class="flex-auto flow-row items-center">
											<div class="font-body text-base text-header-4 text-shadow  font-fit-shrink whitespace-nowrap">
												{props.twoKName}
											</div>
										</div>
									</div>
								</Show>
								<div class="font-body text-sm text-accent-1 mt-1 flex font-fit-shrink whitespace-nowrap">
									<L10n.Compose text={props.playerTitle} />
								</div>
							</div>
						</div>
						<div class="flex h-full -mt-1\.5 mr-0\.5">
							<div class="flex flex-auto">
								<div
									class="w-12 h-12 bg-contain bg-no-repeat self-center"
									style={{ "background-image": `url(${props.badgeIcon})` }}
								>
									<Show when={model.supportsSSO}>
										<div
											class="relative w-8 h-8 -bottom-9 bg-contain bg-no-repeat self-center justify-center bottom-8"
											style={{ "background-image": "url(blp:prof_lvl_bk.png)" }}
										>
											<div class="font-body text-normal text-sm self-center mt-1">
												{props.foundationLevel}
											</div>
										</div>
									</Show>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
			<NavHelp class="absolute -right-2 -top-1" />
		</Activatable>
	);
};
//#endregion

//#

//#region Leader Container
const PauseMenuLeaderContainer: Component<LeaderPortraitAreaProps> = (props) => {
	const model = usePauseMenuContext();

	return (
		<div
			{...props}
			class="relative pause-menu-leader-container pointer-events-none w-76 flex flex-col justify-center items-center"
		>
			<div
				class="pause-menu-leader-image bg-contain bg-no-repeat"
				style={{ "background-image": props.leaderImage }}
			/>
			<Show when={model.supportsSSO}>
				<div class="absolute bottom-10 pause-menu-progression-button">
					<PauseMenuProgressionContainer {...props.progressionBadgeProps} />
				</div>
			</Show>
		</div>
	);
};
//#endregion

//#region GameInfo
const PauseMenuGameInfoContainer: Component<GameInfoProps> = (props) => {
	const model = usePauseMenuContext();
	return (
		<div
			{...props}
			class="flex text-accent-1 text-accent-1 absolute items-center w-full justify-center flex-col"
		>
			<div class="font-shrink pause-menu-game-info">{props.gameInfoString}</div>
			<HSlot>
				<div class="pause-menu-map-seed mt-1 flex flex-row font-shrink">
					<L10n.Compose text="LOC_MAPSEED_NAME" />
					{": "}
					<Show when={model.isClipboardSupported}>
						<Activatable
							class="pause-menu-map-seed-button"
							onActivate={model.onClickMapSeed}
							disableFocus={true}
						>
							{props.mapSeed}
						</Activatable>
					</Show>
					<Show when={!model.isClipboardSupported}>{props.mapSeed}</Show>
				</div>
				<div class="pause-menu-map-seed ml-8 mt-1 flex flex-row font-shrink">
					<L10n.Compose text="LOC_GAMESEED_NAME" />
					{": "}
					<Show when={model.isClipboardSupported}>
						<Activatable
							class="pause-menu-map-seed-button"
							onActivate={model.onClickGameSeed}
							disableFocus={true}
						>
							{props.gameSeed}
						</Activatable>
					</Show>
					<Show when={!model.isClipboardSupported}>{props.gameSeed}</Show>
				</div>
			</HSlot>
			<Show when={model.supportsSSO}>
				<div
					class="pause-menu-build-info-bottom-bar mt-3"
					style={{ color: "rgba(222, 203, 149, 1)" }}
				>
					{props.buildInfo}
				</div>
			</Show>
		</div>
	);
};
//#endregion

//#region Info Container
const PauseMenuInfoContainer: Component<PauseMenuAddonInfoSectionProps> = (props) => {
	const model = usePauseMenuContext();

	const getAddonName = (addon: ModInfo) => {
		if (addon.subscriptionId != null && addon.subscriptionType == "SteamWorkshopContent") {
			return `${Locale.compose(addon.name)} [icon:mod-workshop]`;
		} else {
			return addon.name;
		}
	};

	const openAddonInOverlay = (addon: ModInfo) => {
		if (addon.subscriptionId != null && addon.subscriptionType == "SteamWorkshopContent") {
			Online.Social.activateOverlayToUserGeneratedContent(addon.subscriptionId);
		}
	};

	return (
		<VSlot
			{...props}
			class="pause-menu-info-container relative items-center"
			data-name="pause-menu-info-container"
		>
			<div class="text-xl uppercase font-title font-bold text-secondary mt-4 text-shadow">{props.leaderName}</div>
			<div class="flex flex-row">
				<div
					class="w-40 h-12 bg-contain mr-1"
					style={{ "background-image": "url(blp:base_top-filigree_left)" }}
				/>
				<Show when={model.supportsSSO}>
					<div class="pause-menu-leader-level size-11 text-center font-body-sm bg-contain flex flex-row justify-center items-center">
						<div>{props.level}</div>
					</div>
				</Show>
				<div
					class="w-40 h-12 bg-contain ml-1"
					style={{ "background-image": "url(blp:base_top-filigree_right)" }}
				/>
			</div>
			<div class="text-lg font-title mt-1 mb-3 uppercase font-bold text-shadow">
				<L10n.Compose text={props.civName} />
			</div>
			<Show when={model.supportsSSO}>
				<HSlot
					class="pause-menu-addons-container mt-3 py-1 px-3"
					disableFocus={true}
				>
					<ScrollArea
						class="flex-auto pt-3 pb-2"
						useProxy={true}
					>
						<Show when={props.hasActiveMods}>
							<Show when={props.hasActiveMods && props.hasActiveDLC}>
								<Activatable
									class="w-full text-secondary text-lg font-title uppercase bold flex flex-row relative"
									onActivate={model.onClickCollapseMods}
									disabled={!props.hasActiveDLC}
								>
									<L10n.Compose text="LOC_PAUSE_MENU_MODS_TITLE" />
									<div
										class={`size-10 absolute right-1 -top-3 bg-contain ${!model.isModsCollapsed ? "-rotate-90" : ""}`}
										style={{ "background-image": "url(blp:base_component-arrow)" }}
									/>
								</Activatable>
							</Show>
							<Show when={props.hasActiveMods && !props.hasActiveDLC}>
								<div class="w-full text-secondary text-lg font-title uppercase bold flex flex-row relative mt-3">
									<L10n.Compose text="LOC_PAUSE_MENU_MODS_TITLE" />
								</div>
							</Show>
							<div class="pause-menu-addon-divider w-full h-0\.5 opacity-50 mt-1 mb-2" />
							<Show when={!model.isModsCollapsed}>
								<For each={props.activeMods}>
									{(addon) => (
										<>
											<Activatable
												class="w-full font title uppercase mt-2 mb-1"
												onActivate={() => openAddonInOverlay(addon)}
											>
												<L10n.Stylize text={getAddonName(addon)} />
											</Activatable>
											<div class="pause-menu-addon-divider w-full h-0\.5 opacity-20" />
										</>
									)}
								</For>
							</Show>
						</Show>
						<Show when={props.hasActiveDLC}>
							<Show when={props.hasActiveMods && props.hasActiveDLC}>
								<Activatable
									class="w-full text-secondary text-lg font-title uppercase bold flex flex-row relative mt-3"
									onActivate={model.onClickCollapseAddons}
									disabled={!props.hasActiveMods}
								>
									<L10n.Compose text="LOC_UI_CONTENT_MGR_SUBTITLE" />
									<div
										class={`size-10 absolute right-1 -top-3 bg-contain ${!model.isAddonCollapsed ? "-rotate-90" : ""}`}
										style={{ "background-image": "url(blp:base_component-arrow)" }}
									/>
								</Activatable>
							</Show>
							<Show when={!props.hasActiveMods && props.hasActiveDLC}>
								<div class="w-full text-secondary text-lg font-title uppercase bold flex flex-row relative mt-3">
									<L10n.Compose text="LOC_UI_CONTENT_MGR_SUBTITLE" />
								</div>
							</Show>
							<div class="pause-menu-addon-divider w-full h-0\.5 opacity-50 mt-1 mb-2" />
							<Show when={!model.isAddonCollapsed}>
								<For each={props.activeDLC}>
									{(addon) => (
										<>
											<Activatable
												class="w-full font title uppercase mt-2 mb-1"
												onActivate={() => openAddonInOverlay(addon)}
												audio={EMPTY_ACTIVATABLE_AUDIO}
											>
												<L10n.Stylize text={getAddonName(addon)} />
											</Activatable>
											<div class="pause-menu-addon-divider w-full h-0\.5 opacity-20" />
										</>
									)}
								</For>
							</Show>
						</Show>
						<Show when={!props.hasActiveMods && !props.hasActiveDLC}>
							<div class="self-center justify-center flex flex-row w-full mt-10 break-words flex-wrap">
								<L10n.Compose text="LOC_PAUSE_MENU_NO_ADDONS" />
							</div>
						</Show>
					</ScrollArea>
				</HSlot>
			</Show>

			<Show when={!model.supportsSSO}>
				<div class="items-center">
					<PauseMenuProgressionContainer {...props.progressionBadgeProps} />
				</div>
			</Show>
			<Button
				class="pause-menu-button mt-5"
				onActivate={model.onClickAdvancedOptions}
			>
				<L10n.Compose text="LOC_ADVANCED_OPTIONS_ADVANCED" />
			</Button>
			<Show when={!model.supportsSSO}>
				<div
					class={"pause-menu-build-info-center absolute bottom-2 w-96 max-h-14 text-center font-fit-shrink"}
					style={{ color: "rgba(222, 203, 149, 1)" }}
				>
					{model!.data!.gameInfo.buildInfo}
				</div>
			</Show>
		</VSlot>
	);
};
//#endregion

//region Screen Layout
export interface PauseMenuProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const PauseMenuComponent: Component<PauseMenuProps> = (props) => {
	const model = createPauseMenuModel();
	return (
		<PauseMenuContext.Provider value={model}>
			<Panel
				ref={props.ref}
				name="pause-menu"
				class="h-full w-full pause-menu-fade-in flex flex-col relative"
				id="screen-pause-menu"
			>
				<div class="absolute fullscreen-outside-safezone pause-menu" />
				<Show when={model && model.data}>
					<div class="w-full flex grow relative">
						<div class="bg-accent-6 opacity-60 bottom-0 absolute fullscreen-top-outside-safezone" />
					</div>
					<div class="relative w-full h-1">
						<div class="pause-menu-borders absolute top-0 bottom-0 fullscreen-side-outside-safezone" />
					</div>
					<HSlot class="relative justify-center">
						<div
							style={{ "background-image": "url(blp:base_frame-filigree)" }}
							class="pause-menu-corner-filligree size-45 bg-contain opacity-30 absolute top-5 left-5"
						/>
						<div
							style={{ "background-image": "url(blp:base_frame-filigree)" }}
							class="pause-menu-corner-filligree size-45 bg-contain opacity-30 absolute top-5 right-5 rotate-90"
						/>
						<div
							style={{ "background-image": "url(blp:base_frame-filigree)" }}
							class="pause-menu-corner-filligree size-45 bg-contain opacity-30 absolute bottom-5 left-5 -rotate-90"
						/>
						<div
							style={{ "background-image": "url(blp:base_frame-filigree)" }}
							class="pause-menu-corner-filligree size-45 bg-contain opacity-30 absolute bottom-5 right-5 -rotate-180"
						/>
						<HSlot
							class="pause-menu-main-container w-full flex flex-row relative justify-around"
							data-name="pause-menu-main-container"
						>
							<PauseMenuLeaderContainer {...model!.data!.leaderInfo} />
							<PauseMenuInfoContainer {...model!.data!.addonInfoSectionProps} />
							<PauseMenuButtonContainer />

							<Show when={model.supportsSSO}>
								<div
									class={"pause-menu-build-info-leader absolute bottom-3 left-9"}
									style={{ color: "rgba(222, 203, 149, 1)" }}
								>
									{model!.data!.gameInfo.buildInfo}
								</div>
							</Show>
							<Show when={model.supportsSSO}>
								<Activatable
									class="pause-menu-social-button hover\:scale-110 size-20 transition-transform img-prof-btn-bg flex flex-col items-center justify-center absolute -top-28 right-10 bg-contain bg-no-repeat"
									onActivate={model!.onClickSocialPanel}
									disableFocus={true}
									hotkeyAction="shell-action-2"
									style={{ "transition-duration": "0.1s" }}
								>
									<div class="pause-menu-social-button-img size-18 img-social-icon bg-contain bg-no-repeat" />
									<NavHelp class="absolute -left-6" />
								</Activatable>
							</Show>
						</HSlot>
					</HSlot>
					<div class="relative w-full h-1">
						<div class="pause-menu-borders absolute top-0 bottom-0 fullscreen-side-outside-safezone" />
					</div>
					<div class="w-full flex flex-column grow justify-center relative">
						<div class="bg-accent-6 opacity-60 absolute top-0 fullscreen-bottom-outside-safezone" />
						<PauseMenuGameInfoContainer {...model!.data!.gameInfo} />
					</div>
				</Show>
				<div
					id="clipboard-container"
					class="size-full absolute pointer-events-none opacity-1"
				/>
			</Panel>
		</PauseMenuContext.Provider>
	);
};

export const PauseMenu = ComponentRegistry.register({
	name: "PauseMenu",
	styles: [style],
	createInstance: PauseMenuComponent,
});

//#endregion
